const recordETAObservation = `-- name: RecordETAObservation :exec
INSERT INTO eta_observations (origin_h3_r8, destination_h3_r8, hour_band, samples, total_seconds)
VALUES ($1, $2, $3, 1, $4)
ON CONFLICT (origin_h3_r8, destination_h3_r8, hour_band)
DO UPDATE SET samples = eta_observations.samples + 1, total_seconds = eta_observations.total_seconds + EXCLUDED.total_seconds, updated_at = now()
`

type RecordETAObservationParams struct {
	OriginH3R8      int64 `json:"origin_h3_r8"`
	DestinationH3R8 int64 `json:"destination_h3_r8"`
	HourBand        int16 `json:"hour_band"`
	TotalSeconds    int64 `json:"total_seconds"`
}

func (q *Queries) RecordETAObservation(ctx context.Context, arg RecordETAObservationParams) error {
	_, err := q.db.Exec(ctx, recordETAObservation,
		arg.OriginH3R8,
		arg.DestinationH3R8,
		arg.HourBand,
		arg.TotalSeconds,
	)
	return err
}

